const items=$input.all();
const out=[];
for(const it of items){ const j=it.json||{}; if(!j.alert_key) continue; const esc=s=>String(s==null?'':s).replace(/'/g,"''"); const q="INSERT INTO cost_alerts (alert_key, threshold_usd, last_value_usd, sent_at) VALUES ('"+esc(j.alert_key)+"',"+(parseFloat(j.threshold)||0)+","+(parseFloat(j.value)||0)+",now()) ON CONFLICT (alert_key) DO UPDATE SET last_value_usd=EXCLUDED.last_value_usd, sent_at=now()"; out.push({ json:{ alert_key:j.alert_key, msg:j.msg||'', threshold:j.threshold, value:j.value, query:q } }); }
return out;
